import { describe, it, expect } from 'vite-plus/test'

import { crc32, zipStream } from '../lib/zip.js'
import { collectStream, parseZip } from './support/zipreader.js'

// The stored-ZIP writer (ahaqqu/RumaQ#440 — ticket 6's dependency-free
// archive format). Every test parses the generated bytes with the SHARED
// hand-written reader (support/zipreader.ts — T6-B1; the export suite uses
// the same one, so a malformed writer fails identically in both). No
// third-party parser exists to lean on (the whole point is no new
// dependency), and the reader IS the validation: signatures, method 0, the
// UTF-8 flag, real sizes/CRC in local headers, and a central directory that
// lands exactly at the EOCD.

// RFC 1952's worked example — the pin that the CRC-32 table/shifts are the
// IEEE 802.3 parameters, not a lookalike.
it('crc32 matches the standard vector', () => {
  expect(crc32(new TextEncoder().encode('123456789'))).toBe(0xcbf43926)
})

async function collect(entries: Parameters<typeof zipStream>[0]): Promise<Uint8Array<ArrayBuffer>> {
  return collectStream(zipStream(entries))
}

describe('stored zip writer (ticket 6 #440)', () => {
  it('round-trips entries: names, bytes and sizes survive the archive', async () => {
    const payload = new TextEncoder().encode('isi dokumen, dengan koma & "quotes"\r\n')
    const bytes = await collect([
      { name: 'documents.csv', data: payload },
      { name: 'files/ktp.jpg', data: new Uint8Array([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3]) },
    ])
    const entries = parseZip(bytes)
    expect(entries.size).toBe(2)
    expect([...entries.keys()].sort()).toEqual(['documents.csv', 'files/ktp.jpg'])
    expect(entries.get('documents.csv')?.size).toBe(payload.byteLength)
    expect([...entries.get('documents.csv')!.bytes]).toEqual([...payload])
    expect([...entries.get('files/ktp.jpg')!.bytes]).toEqual([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3])
  })

  it('writes a valid empty archive (EOCD with zero entries)', async () => {
    const bytes = await collect([])
    expect(parseZip(bytes).size).toBe(0)
  })

  it('decodes non-ASCII names (UTF-8 flag round-trip)', async () => {
    const bytes = await collect([
      { name: 'files/d1/1-Dok KTP₂ & akta.pdf', data: new Uint8Array([1, 2]) },
    ])
    expect([...parseZip(bytes).keys()]).toEqual(['files/d1/1-Dok KTP₂ & akta.pdf'])
  })

  it('resolves lazy loaders as the stream pulls, in entry order', async () => {
    const order: string[] = []
    const bytes = await collect([
      {
        name: 'a',
        data: () => {
          order.push('a')
          return new Uint8Array([1])
        },
      },
      {
        name: 'b',
        data: async () => {
          order.push('b')
          return new Uint8Array([2, 2])
        },
      },
    ])
    expect(order).toEqual(['a', 'b'])
    expect(parseZip(bytes).get('b')?.size).toBe(2)
  })

  it('encodes the entry timestamp as a DOS date/time (UTC)', async () => {
    const modified = new Date(Date.UTC(2026, 10, 7, 9, 30, 20))
    const bytes = await collect([{ name: 'a', data: new Uint8Array([1]), modified }])
    const entry = parseZip(bytes).get('a')!
    expect(entry.dosDate).toBe(((2026 - 1980) << 9) | (11 << 5) | 7)
    expect(entry.dosTime).toBe((9 << 11) | (30 << 5) | 10) // 2-second resolution
  })

  it('cancels without pulling the remaining entries (aborted download stops storage reads)', async () => {
    const pulled: string[] = []
    const stream = zipStream([
      {
        name: 'a',
        data: () => {
          pulled.push('a')
          return new Uint8Array([1])
        },
      },
      {
        name: 'b',
        data: () => {
          pulled.push('b')
          return new Uint8Array([2])
        },
      },
    ])
    const reader = stream.getReader()
    await reader.read()
    await reader.cancel()
    await new Promise((resolve) => setTimeout(resolve, 0))
    expect(pulled).toEqual(['a'])
  })
})
